def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        safe = DAILY_SALARY * 0.25
        return max(0.0, min(budget, safe))

    prev_bids = []
    aggressive = 0
    desperate = 0
    zeroish = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 100:
                aggressive += 1
            if bid <= 1:
                zeroish += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate += 1

    units = supply / WATER_REQ
    base = DAILY_SALARY * 0.42

    if units >= 1.9:
        base = DAILY_SALARY * 0.32
    elif units <= 1.25:
        base = DAILY_SALARY * 0.78
    elif units <= 1.55:
        base = DAILY_SALARY * 0.58

    if prev_bids:
        top_prev = max(prev_bids)
        low_prev = min(prev_bids)
        if top_prev >= 140:
            base = min(base, DAILY_SALARY * 0.38)
        elif top_prev >= 110:
            base = max(base, DAILY_SALARY * 0.52)
        elif top_prev <= 5:
            base = min(base, DAILY_SALARY * 0.28)
        if low_prev <= 1 and units >= 1.5:
            base = min(base, DAILY_SALARY * 0.26)

    if aggressive >= 2 and hp >= 6 and no_water == 0:
        base = min(base, DAILY_SALARY * 0.24)

    if desperate >= 2 and units < 1.7:
        base = max(base, DAILY_SALARY * 0.7)

    if hp <= 2 or no_water >= 2:
        base = max(base, DAILY_SALARY * 1.08)
    elif hp <= 4 or no_water >= 1:
        base = max(base, DAILY_SALARY * 0.88)

    if budget < DAILY_SALARY * 1.2:
        base = min(base, budget)
    elif budget > 500 and (hp <= 4 or units < 1.4):
        base = max(base, DAILY_SALARY * 0.95)

    bid = round(max(0.0, min(budget, base)), 2)
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from immediate previous_trace only
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Estimate how aggressive the field was yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_highest_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_highest_prev_bid = float(sorted_bids[1])

    # If my hp is critical, spend to avoid death
    if my_hp <= 2:
        target = DAILY_SALARY * 0.92
    elif my_hp <= 4:
        target = DAILY_SALARY * 0.65
    else:
        # Otherwise, bid just enough to beat typical aggressive bids.
        # If yesterday's highest bid was extremely high, don't match it; bid around the middle.
        if highest_prev_bid >= DAILY_SALARY * 1.2:
            target = max(DAILY_SALARY * 0.5, second_highest_prev_bid + 2.0)
        else:
            # Moderate bids: bid slightly above the highest to secure water when needed.
            target = max(DAILY_SALARY * 0.48, highest_prev_bid * 0.75 + 5.0)

    # Budget and supply-aware cap
    # Higher supply reduces need to overbid.
    supply_factor = 1.0
    if supply >= 22.0:
        supply_factor = 0.75
    elif supply >= 18.0:
        supply_factor = 0.9
    else:
        supply_factor = 1.05

    bid = target * supply_factor

    # Hard cap to avoid bankrupting; keep some buffer for later days
    # (budget is in same scale as bids)
    max_affordable = my_budget
    if my_budget > 0:
        # Keep at least 10% of budget if possible
        max_affordable = max(0.0, my_budget * 0.9)

    bid = min(bid, max_affordable)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], avg_opp_bid * 1.2)
    elif my_status['hp'] > 7:
        bid = min(my_status['budget'], avg_opp_bid * 0.7)
    else:
        bid = min(my_status['budget'], avg_opp_bid * 0.95)

    return max(0.0, float(bid))
